    "description": "美国太空探索技术公司重型运载火箭“星舰”于美国中部时间24日下午从得克萨斯州南部的发射基地升空，实施第13次试飞。 据该公司介绍，本次任务将继续验证新一代“星舰”系统的性能，并首次部署20颗新一代“星链”卫星。按计划，火箭第一级“超级重型”助推器将在墨西哥湾附近海域实施受控溅落，不返回发射场进行回收；第二级“星舰”飞船将在完成试飞后，在印度洋预定区域溅落。",
    "content": "美国太空探索技术公司重型运载火箭“星舰”于美国中部时间24日下午从得克萨斯州南部的发射基地升空，实施第13次试飞。 据该公司介绍，本次任务将继续验证新一代“星舰”系统的性能，并首次部署20颗新一代“星链”卫星。按计划，火箭第一级“超级重型”助推器将在墨西哥湾附近海域实施受控溅落，不返回发射场进行回收；第二级“星舰”飞船将在完成试飞后，在印度洋预定区域溅落。"
