    "title": "也门胡塞武装称沙特空袭也门多地",
    "link": "http://www.news.cn/20260725/80160ecee7ab4bc4ac860ccb1dc9afca/c.html",
    "pub_date": "2026-07-25 06:58:40",
    "author": "尹炣,罗晨,王海洲",
    "description": "新华社科威特城7月24日电（记者尹炣）也门胡塞武装24日晚称，沙特对该组织控制的红海港口城市荷台达发动空袭，位于红海的也门卡马兰岛也遭到袭击。 据胡塞武装控制的马西拉电视台报道说，沙特对也门荷台达省首府荷台达市电信设施等发动连续空袭。 荷台达市居民对新华社记者说，空袭的剧烈爆炸声响彻该市，火光和浓烟从市中心多个地点升起。 据沙特阿拉伯通讯社报道，一艘隶属沙特公司的船舶24日在红海航行时遭袭击，船体轻微受损，无人员伤亡。在确认安全后，该船…",
    "content": "新华社科威特城7月24日电（记者尹炣）也门胡塞武装24日晚称，沙特对该组织控制的红海港口城市荷台达发动空袭，位于红海的也门卡马兰岛也遭到袭击。 据胡塞武装控制的马西拉电视台报道说，沙特对也门荷台达省首府荷台达市电信设施等发动连续空袭。 荷台达市居民对新华社记者说，空袭的剧烈爆炸声响彻该市，火光和浓烟从市中心多个地点升起。 据沙特阿拉伯通讯社报道，一艘隶属沙特公司的船舶24日在红海航行时遭袭击，船体轻微受损，无人员伤亡。在确认安全后，该船已继续驶往目的地。 也门胡塞武装20日宣布对沙特实施海上禁运，并警告国际航运公司…"
