    "content": "新华社联合国7月24日电（记者尚绪谦）联合国秘书长古特雷斯24日通过发言人迪雅里克发表声明，对也门胡塞武装恢复袭击红海商船并威胁红海通航表示震惊，呼吁局势立即降级。 声明说，胡塞武装袭击商船进一步加剧地区紧张局势并让也门进一步深陷冲突风险。新的敌对行动将破坏也门和平前景并导致地区及域外出现严重的经济、人道主义和环境后果。 声明说，古特雷斯呼吁立即降级紧张局势，敦促胡塞武装不要发动新的袭击或采取其他升级行为。曼德海峡及附近海域通航权利及自由必须完全恢复。 也门胡塞武装20日宣布对沙特实施海上禁运。23日，胡塞武装称，…"
