    "content": "老婆恢复的不错，我能回去工作了。回自己的工作室觉得无聊，想远离城市。想去云南旅居几个月。 没显示器是一点不行的。眼睛也不太好了，本子只能看看视频，不能拿来干活。 所以便携成了最大的痛。有人说本地买个 27 随便用用。 含，我家里连工作室已经 6 台显示器了。真不想买大块头了，但也不想带，太重了。最好有双屏无缝组合的。 顺便，看看有没有什么青年养老院，或者做民宿的小伙伴，提前考虑晚年的归宿。 主要身体也不行了，工作自由，大不了不干了，炒炒股拉倒了。种菜才是王道。"
