    "content": "新华社伦敦7月24日电（记者张亚东）英国伦敦股市《金融时报》100种股票平均价格指数24日报收于10736.23点，较前一交易日上涨97.06点，涨幅为0.91%。欧洲三大股指当天全线上涨。 当天伦敦股市成分股中位于涨幅前五位的个股分别为：励讯集团股价上涨4.77%，软件公司赛奇股价上涨4.45%，罗尔斯罗伊斯控股公司股价上涨4.16%，约翰-戴维运动时装公司股价上涨3.71%，梅特伦能源与金属公司股价上涨3.48%。 当天伦敦股市成分股中位于跌幅前五位的个股分别为：电信运营商非洲电信公司股价下跌3.30%，英国石…"
