    "content": "新华社纽约7月24日电（记者施春 杨士龙）“你好！中国”推介招待会23日在纽约林肯表演艺术中心举行，美国文艺、旅游、媒体等各界代表约200人出席。 此次活动在林肯中心2026年“城市之夏艺术节·中国艺术周”期间举办，由中国对外文化交流协会与中国驻纽约旅游办事处联合主办。招待会以醒狮和英歌表演开场，热烈奔放的节奏瞬间点燃全场气氛，功夫街舞传递出活力四射的现代气息。现场还设置了“你好！中国”旅游展示专区，通过播放中国旅游宣传片等，介绍中国旅游资源、文旅融合新场景及旅行便利化政策。 中国驻纽约副总领事马萧萧在致辞中表示，…"
