    "content": "新华社吉尔吉斯斯坦乔尔蓬阿塔7月24日电 中共中央政治局委员、外交部长王毅24日在吉尔吉斯斯坦出席上海合作组织外长理事会会议。上合组织成员国外长及上合组织秘书长、地区反恐怖机构执委会主任等出席。 王毅表示，上合组织天津峰会对未来10年发展作出战略擘画，开启了上合高质量发展新阶段。一年来，中方落实习近平主席提出的重大倡议，以“中国行动”赋能地区发展。绿色产业、数字经济、科技创新、能源、高等教育、职业技术教育、人工智能7个应用平台全部启用，形成160多个项目。经贸合作高质量发展行动计划持续实施，中国同各成员国贸易稳步增…"
