    "content": "快科技7月24日消息， 今日，中国香港TVB官宣正式更名为无线集团，由传统电视台升级为跨媒体娱乐集团。 集团业务将更多元化，拥抱创新AI技术，市场拓宽到大湾区，TVB同时强调好内容永远是我们的根基和坚持。 从官方公告获悉，TVB中文名称由“电视广播有限公司”更改为“无线集团有限公司”，英文名称由Television Broadcasts Limited更改为TVB Limited。 无线集团行政主席许涛在致辞中表示，由1967年启播以来，无线已扎根香港超过半世纪，记载了香港的历史，亦承载了几代香港人的集体回忆。 我…"
