    "content": "7月24日，中方在四川省成都市主办APEC人工智能高级别论坛，论坛主题为“促进人工智能普惠包容发展”。APEC成员经济体重申，我们致力于在人工智能领域深化交流、凝聚共识、加强合作、促进创新，并致力于继续实施《2040年APEC布特拉加亚愿景》、《APEC互联网和数字经济路线图》和《APEC人工智能倡议(2026—2030)》。"
