    "pub_date": "2026-07-24 23:33:45",
    "author": "",
    "description": "中国和菲律宾公务船连续第二天在有主权争议的黄岩岛（菲称斯卡伯勒浅滩）海域爆发摩擦，是双方五天内三度在南中国海对峙。马尼拉还两度指责中国海警船向菲国船只发射水炮，称两国官船星期五（7月24日）仅相距约七米，构成严重碰撞风险；北京则反指菲律宾船只蓄意冲闯在先。 受访学者研判，尽管本轮摩擦不至于失控，但菲律宾在多国外长本周齐聚马尼拉期间升级摩擦，意在借助舆论战获取不对称优势，寻求进一步推动南中国海问题国际化与北京周旋对抗。 中国海警局新闻发言…",
    "content": "中国和菲律宾公务船连续第二天在有主权争议的黄岩岛（菲称斯卡伯勒浅滩）海域爆发摩擦，是双方五天内三度在南中国海对峙。马尼拉还两度指责中国海警船向菲国船只发射水炮，称两国官船星期五（7月24日）仅相距约七米，构成严重碰撞风险；北京则反指菲律宾船只蓄意冲闯在先。 受访学者研判，尽管本轮摩擦不至于失控，但菲律宾在多国外长本周齐聚马尼拉期间升级摩擦，意在借助舆论战获取不对称优势，寻求进一步推动南中国海问题国际化与北京周旋对抗。 中国海警局新闻发言人姜略星期五通报，菲律宾当天组织七艘公务船、三艘海警舰、一艘运鱼船，并唆使大量渔…"
