    "content": "新华社成都7月24日电（记者张海磊）作为2026年亚太经合组织（APEC）数字周重要活动之一，7月24日，2026年APEC人工智能高级别论坛在四川省成都市举办。论坛发布成果文件《APEC人工智能高级别论坛关于促进亚太地区人工智能发展的声明》。 声明从安全发展、负责任部署、创新环境、普惠合作等四个方面规划了APEC人工智能未来合作路径，凝聚了各经济体进一步深化人工智能合作的共识，为未来合作奠定了坚实基础。同时，中方宣布将在深圳前海设立“促进APEC数据跨境流动合作中国中心”，推动构建一个集政策研究、规则对接、产业服…"
