    "description": "新华社香港7月24日电（奚天麒）根据香港特区政府日前公布的“粤车南下”扩展安排，“粤车南下”入境香港市区措施25日起将进一步扩容，覆盖范围扩展至粤港澳大湾区9个内地城市。 新增城市包括深圳、佛山、东莞、惠州及肇庆，每日预约名额由100辆增至200辆，旅客留港日数维持最多3天不变。 去年12月，“粤车南下”计划率先开放广州、珠海、江门、中山4市作为试点。粤港双方将持续留意实施安排，并视实施情况，力争在2027年第一季度或之前，将相关安排推…",
    "content": "新华社香港7月24日电（奚天麒）根据香港特区政府日前公布的“粤车南下”扩展安排，“粤车南下”入境香港市区措施25日起将进一步扩容，覆盖范围扩展至粤港澳大湾区9个内地城市。 新增城市包括深圳、佛山、东莞、惠州及肇庆，每日预约名额由100辆增至200辆，旅客留港日数维持最多3天不变。 去年12月，“粤车南下”计划率先开放广州、珠海、江门、中山4市作为试点。粤港双方将持续留意实施安排，并视实施情况，力争在2027年第一季度或之前，将相关安排推广至广东全省21市。 香港特区政府运输署表示，“粤车南下”计划实施以来，整体运作…"
