    "content": "新华社哈尔滨7月24日电（记者梁书斌）黑龙江省纪委监委7月24日通报，日前，经黑龙江省委批准，黑龙江省纪委监委对牡丹江市政协原党组书记、主席王志刚严重违纪违法问题进行了立案审查调查。 经查，王志刚丧失理想信念，背弃初心使命，不信马列信鬼神，搞迷信活动；无视中央八项规定精神，违规收受礼金、借用管理服务对象房产、接受宴请及住宿安排；违背组织原则，在干部选拔任用等工作中为他人谋取利益并收受钱款；廉洁底线失守，违规从事营利活动；违反国家法律法规，指使他人向公安机关作伪证；与不法商人沆瀣一气，大搞权钱交易，利用职务上的便利，…"
