    "description": "新华社香港7月24日电 香港贸易发展局（简称“贸发局”）24日宣布，推出优化全球网络资源措施，全力协助企业深耕传统市场，并拓展中亚、中东、北非等高增长市场。 贸发局表示，随着全球经济重心逐步向新兴市场转移，以及企业出海步伐加快，贸发局积极优化全球资源，以把握高增长市场带来的机遇。 贸发局主席马时亨24日在记者会上表示，香港特区行政长官李家超6月率领代表团出访哈萨克斯坦及乌兹别克斯坦，为香港企业打开新大门，并带来庞大商机。贸发局将积极跟进…",
    "content": "新华社香港7月24日电 香港贸易发展局（简称“贸发局”）24日宣布，推出优化全球网络资源措施，全力协助企业深耕传统市场，并拓展中亚、中东、北非等高增长市场。 贸发局表示，随着全球经济重心逐步向新兴市场转移，以及企业出海步伐加快，贸发局积极优化全球资源，以把握高增长市场带来的机遇。 贸发局主席马时亨24日在记者会上表示，香港特区行政长官李家超6月率领代表团出访哈萨克斯坦及乌兹别克斯坦，为香港企业打开新大门，并带来庞大商机。贸发局将积极跟进相关工作，加强哈萨克斯坦阿拉木图顾问办事处的资源，以提升对中亚地区的支援。 中东…"
