    "title": "Vlog丨一起来逛第34届全国图书交易博览会",
    "link": "http://www.news.cn/20260724/f26d15b2e0804bcc8c0883f656e4d49f/c.html",
    "pub_date": "2026-07-24 22:10:52",
    "author": "王怿文,宋立峰,刘铭翔",
    "description": "7月24日，第34届全国图书交易博览会在浙江杭州开幕。本届书博会以“书香中国 阅读之美”为主题，持续至7月27日，全国数千家出版发行单位携上百万种书籍和文创产品参会。新华社记者带你逛书博会，共同感受“中国历代绘画大系”中的阅读之美，体验“宋韵书香”。 记者：王怿文、宋立峰、刘铭翔 新华社音视频部制作",
