    "description": "赛得利集团与保护国际基金会（CI）的合作，为项目打下了坚实的基础，并形成了协同共治的生态保护网络。 南方周末研究员 邹力 责任编辑：孙孝文 每年秋冬之交，成千上万的白鹤、灰鹤、白头鹤、白枕鹤会来到江西省余干县插旗洲，形成千鹤翔舞的壮丽景象。 监测数据显示，鄱阳湖候鸟数量已达70万只，白鹤、白头鹤、东方白鹳、青头潜鸭等珍稀候鸟频频现身。而在最高峰时段，约有10万只候鸟聚集插旗洲，其中仅白鹤就有3000多只，占全球白鹤总量的一半。 作为中国…",
    "content": "赛得利集团与保护国际基金会（CI）的合作，为项目打下了坚实的基础，并形成了协同共治的生态保护网络。 南方周末研究员 邹力 责任编辑：孙孝文 每年秋冬之交，成千上万的白鹤、灰鹤、白头鹤、白枕鹤会来到江西省余干县插旗洲，形成千鹤翔舞的壮丽景象。 监测数据显示，鄱阳湖候鸟数量已达70万只，白鹤、白头鹤、东方白鹳、青头潜鸭等珍稀候鸟频频现身。而在最高峰时段，约有10万只候鸟聚集插旗洲，其中仅白鹤就有3000多只，占全球白鹤总量的一半。 作为中国最大的淡水湖，鄱阳湖流域面积为16.22万平方公里，流域内生物多样性丰富。然而，…"
