    "description": "中国农牧装备正加速走向世界。销售网络覆盖全球100多个国家和地区，与79个共建“一带一路”国家建立长期合作关系，丰尚公司深耕农牧装备领域，是全球领先的饲料和食品工程解决方案提供商、农牧装备全产业链系统服务商。 以“全球研发、本土服务”为策略，公司在全球布局了6个生产基地、5个研发中心。 2025年公司销售额超50亿元，全年出口额约3.06亿美元，同比增长28%。 记者：黄培锋 新华社音视频部制作",
    "content": "中国农牧装备正加速走向世界。销售网络覆盖全球100多个国家和地区，与79个共建“一带一路”国家建立长期合作关系，丰尚公司深耕农牧装备领域，是全球领先的饲料和食品工程解决方案提供商、农牧装备全产业链系统服务商。 以“全球研发、本土服务”为策略，公司在全球布局了6个生产基地、5个研发中心。 2025年公司销售额超50亿元，全年出口额约3.06亿美元，同比增长28%。 记者：黄培锋 新华社音视频部制作"
