    "content": "你有两个ESP：一个Manjaro的，一个Windows的，分别位于两块硬盘上。这本身没什么问题。 符: Available Boot Loaders on ESP: ESP: /boot/efi (/dev/disk/by-partuuid/afeee102-2730-4b2c-8a11-4c7992d1bc6c) File: └─/boot/efi//EFI/BOOT/bootx64.efi 这里还有一个位于默认位置的引导项，和你的「Manjaro」引导项位于同一个ESP上，但是是另外的文件。 推测这个 boo…"
