    "content": "新华社北京7月24日电 题：建设扎实推进 效益持续发挥——水利部介绍上半年水利基础设施建设进展 新华社记者魏弘毅 “十五五”开局之年已然过半，我国水利基础设施建设成效如何？水利部24日举办新闻发布会，介绍相关情况。 水利部副部长孙志禹介绍，今年1至6月全国实施水利项目约3.3万个，完成水利建设投资5151亿元。水利基础设施建设吸纳就业134.4万人，其中农村劳动力111.1万人；发放就业人员工资209.9亿元，其中农村劳动力工资165.1亿元。 上半年全国新开工重大水利工程25项，接近去年全年开工数量，其中包括三峡…"
